in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 uv0;
out vec2 worldXY;
vec4 vert(){
  vec4 pos=vec4(a_position,1);
  #if USE_LOCAL
  pos=cc_matWorld*pos;
  #endif
  worldXY=pos.xy;
  #if USE_PIXEL_ALIGNMENT
  pos=cc_matView*pos;pos.xyz=floor(pos.xyz);pos=cc_matProj*pos;
  #else
  pos=cc_matViewProj*pos;
  #endif
  uv0=a_texCoord;
  #if SAMPLE_FROM_RT
  uv0 = cc_cameraPos.w > 1.0 ? vec2(uv0.x, 1.0 - uv0.y) : uv0;
  #endif
  color=a_color;return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
in vec2 uv0;
in vec2 worldXY;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform LifeRig {
  vec4 eye0;vec4 eye1;vec4 ear0;vec4 ear1;
  vec4 earPivot0;vec4 earPivot1;vec4 tailRegion;vec4 tailPivot;
  vec4 fishRegion;vec4 fishPivot;vec4 faceAngle;vec4 motion;
  vec4 bellyRegion;vec4 ultimate;vec4 poseWipe;vec4 pawRegion;vec4 pawPivot;vec4 pawMotion;
};
vec2 rotatePoint(vec2 p,float a){float c=cos(a),s=sin(a);return vec2(c*p.x-s*p.y,s*p.x+c*p.y);}
vec2 localTurn(vec2 p,vec4 region,vec2 pivot,float a){
  float w=1.0-smoothstep(0.48,1.0,length((p-region.xy)/region.zw));
  return mix(p,pivot+rotatePoint(p-pivot,-a),w);
}
vec2 closeEye(vec2 uv,vec4 eye,float amount){
  vec2 p=rotatePoint(uv-eye.xy,-faceAngle.x);
  float w=1.0-smoothstep(eye.z*0.82,eye.z*1.10,abs(p.x));
  float inner=eye.w*sqrt(max(0.04,1.0-pow(p.x/eye.z,2.0)));
  float outer=eye.w*1.72;
  float scale=1.0-0.94*amount,dest=inner*scale,y=abs(p.y),mapped=y;
  if(y<dest)mapped=y/scale;
  else if(y<outer)mapped=inner+(y-dest)*(outer-inner)/(outer-dest);
  p.y=mix(p.y,sign(p.y)*mapped,w);
  return eye.xy+rotatePoint(p,faceAngle.x);
}
float closedLid(vec2 uv,vec4 eye){
  vec2 p=rotatePoint(uv-eye.xy,-faceAngle.x);
  float width=eye.z*0.80;
  float across=1.0-smoothstep(width*0.88,width,abs(p.x));
  float curve=-eye.w*0.035*(1.0-pow(clamp(p.x/width,-1.0,1.0),2.0));
  float halfLine=eye.w*0.072+0.0008;
  return across*(1.0-smoothstep(halfLine*0.65,halfLine,abs(p.y-curve)));
}
vec4 frag(){
  vec2 p=uv0;
  vec2 q=(p-bellyRegion.xy)/bellyRegion.zw;
  float w=1.0-smoothstep(0.2,1.0,length(q));
  p=bellyRegion.xy+(p-bellyRegion.xy)/(1.0+w*(ultimate.x+ultimate.y));
  #if !POSE_FRAME
  vec2 leftPaw=vec2(660.0,750.0)/1254.0,rightPaw=vec2(825.0,735.0)/1254.0;
  float leftMask=1.0-smoothstep(0.3,1.0,length((p-leftPaw)/vec2(0.085,0.080)));
  float rightMask=1.0-smoothstep(0.3,1.0,length((p-rightPaw)/vec2(0.065,0.075)));
  p+=vec2(-0.045,0.025)*leftMask*ultimate.x+vec2(0.035,0.025)*rightMask*ultimate.x;
  #endif
  float a=atan(q.y,q.x);
  p+=q*ultimate.y*0.007*sin(a*14.0)*w;
  p.x+=ultimate.w*w;
  if(abs(pawMotion.x)>0.00001)p=localTurn(p,pawRegion,pawPivot.xy,pawMotion.x);
  if(abs(motion.y)>0.00001){p=localTurn(p,ear0,earPivot0.xy,motion.y);p=localTurn(p,ear1,earPivot1.xy,-motion.y*0.75);}
  if(abs(motion.z)>0.00001)p=localTurn(p,tailRegion,tailPivot.xy,motion.z);
  if(abs(motion.w)>0.00001)p=localTurn(p,fishRegion,fishPivot.xy,motion.w);
  #if !POSE_FRAME
  if(motion.x>0.00001){p=closeEye(p,eye0,motion.x);p=closeEye(p,eye1,motion.x);}
  #else
  if(p.x<0.0||p.y<0.0||p.x>1.0||p.y>1.0)return vec4(0.0);
  #endif
  vec4 o=CCSampleWithAlphaSeparated(cc_spriteTexture,p)*color;
  #if !POSE_FRAME
  float eyeLight=0.0;
  eyeLight+=1.0-smoothstep(0.0,0.75,length((uv0-eye0.xy)/eye0.zw));
  eyeLight+=1.0-smoothstep(0.0,0.75,length((uv0-eye1.xy)/eye1.zw));
  o.rgb=mix(o.rgb,vec3(1.0,0.95,0.75),min(0.30,eyeLight*ultimate.z*0.25));
  float lid=max(closedLid(uv0,eye0),closedLid(uv0,eye1))*smoothstep(0.72,0.96,motion.x);
  o.rgb=mix(o.rgb,vec3(0.28,0.17,0.12),lid*o.a);
  #else
  if(o.a<0.02)o=vec4(0.0);
  #endif
  if(abs(poseWipe.w)>0.5){
    float incoming=1.0-smoothstep(poseWipe.z-3.0,poseWipe.z+3.0,length(worldXY-poseWipe.xy));
    o.a*=poseWipe.w>0.0?incoming:1.0-incoming;
  }
  ALPHA_TEST(o);return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

